'use strict';

// MODULES //

var tape = require( 'tape' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var abs = require( '@stdlib/math/base/special/abs' );
var NINF = require( '@stdlib/constants/float64/ninf' );
var EPS = require( '@stdlib/constants/float64/eps' );
var cdf = require( './../lib' );


// FIXTURES //

var data = require( './fixtures/julia/data.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof cdf, 'function', 'main export is a function' );
	t.end();
});

tape( 'if provided `NaN` for any parameter, the function returns `NaN`', function test( t ) {
	var y;

	y = cdf( NaN, 1.0, 1.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = cdf( 0.5, NaN, 1.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = cdf( 0.5, 1.0, NaN );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = cdf( NaN, NaN, NaN );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided a non-positive `alpha`, the function returns `NaN`', function test( t ) {
	var y;

	y = cdf( 1.0, 0.0, 1.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = cdf( 1.0, -1.0, 1.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = cdf( 1.0, NINF, 1.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided a non-positive `beta`, the function returns `NaN`', function test( t ) {
	var y;

	y = cdf( 1.0, 1.0, 0.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = cdf( 1.0, 1.0, -1.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = cdf( 1.0, 1.0, NINF );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided `x <= 0`, the function returns `0`', function test( t ) {
	var y;

	y = cdf( 0.0, 1.0, 1.0 );
	t.strictEqual( y, 0.0, 'returns expected value' );

	y = cdf( -1.0, 1.0, 1.0 );
	t.strictEqual( y, 0.0, 'returns expected value' );

	y = cdf( -10.0, 2.0, 3.0 );
	t.strictEqual( y, 0.0, 'returns expected value' );

	y = cdf( NINF, 1.0, 1.0 );
	t.strictEqual( y, 0.0, 'returns expected value' );

	t.end();
});

tape( 'the function does not overflow for large `x` (approaching one)', function test( t ) {
	var y;

	y = cdf( 1.0e6, 1.0, 60.0 );
	t.strictEqual( y, 1.0, 'returns expected value' );

	y = cdf( 1.0e300, 1.0, 5.0 );
	t.strictEqual( y, 1.0, 'returns expected value' );

	t.end();
});

tape( 'the function evaluates the log-logistic cdf for positive `x`, `alpha`, and `beta`', function test( t ) {
	var expected;
	var alpha;
	var delta;
	var beta;
	var tol;
	var x;
	var y;
	var i;

	expected = data.expected;
	x = data.x;
	alpha = data.alpha;
	beta = data.beta;
	for ( i = 0; i < x.length; i++ ) {
		y = cdf( x[ i ], alpha[ i ], beta[ i ] );
		if ( expected[ i ] !== null && !( expected[ i ] === 0.0 && y < EPS ) ) {
			if ( y === expected[ i ] ) {
				t.strictEqual( y, expected[ i ], 'x: '+x[ i ]+', alpha: '+alpha[ i ]+', beta: '+beta[ i ]+', y: '+y+', expected: '+expected[ i ] );
			} else {
				delta = abs( y - expected[ i ] );
				tol = 3.0 * EPS * abs( expected[ i ] );
				t.ok( delta <= tol, 'within tolerance. x: '+x[ i ]+'. alpha: '+alpha[ i ]+'. beta: '+beta[ i ]+'. y: '+y+'. E: '+expected[ i ]+'. Δ: '+delta+'. tol: '+tol+'.' );
			}
		}
	}
	t.end();
});
